<?php
/** Fluent 2: Microsoft's design system, its principles, tokens and theming, materials like Mica and Acrylic, Windows app patterns. */

return [
    'id' => 'fluent', 'family' => 'fluent', 'after' => 'ui-base', 'categories' => ['design', 'desktop'],
    'title' => L('Fluent Design', 'Fluent Design'), 'short' => L('Fluent', 'Fluent'), 'level' => L('Intermedio', 'Intermediate'),
    'desc' => L('Il design system di Microsoft per Windows, Microsoft 365 e il web: principi di Fluent 2, token e temi, materiali Mica e Acrylic, componenti e layout delle app Windows.', 'Microsoft’s design system for Windows, Microsoft 365 and the web: Fluent 2 principles, tokens and themes, Mica and Acrylic materials, components and Windows app layouts.'),
    'lessons' => [
        lesson('principles', L('Che cos’è Fluent 2', 'What Fluent 2 is'), [
            P('**Fluent** è il design system di Microsoft, usato in Windows 11, Teams, Outlook, Office e Azure. La versione **Fluent 2** unisce un’unica base di design per web, Windows, iOS e Android, con librerie come **Fluent UI React** (web), **WinUI 3** (app Windows native) e kit per Figma.', '**Fluent** is Microsoft’s design system, used in Windows 11, Teams, Outlook, Office and Azure. **Fluent 2** unifies a single design foundation for web, Windows, iOS and Android, with libraries such as **Fluent UI React** (web), **WinUI 3** (native Windows apps) and Figma kits.'),
            P('I suoi principi parlano di esperienze **naturali su ogni dispositivo** (si adatta a mouse, tastiera, penna, touch e alle convenzioni di ogni piattaforma), **costruite per la concentrazione** (interfacce calme che lasciano spazio al lavoro), **per tutti** (accessibilità e inclusione dall’inizio) e **inconfondibilmente Microsoft**.', 'Its principles speak of experiences **natural on every device** (adapting to mouse, keyboard, pen, touch and each platform’s conventions), **built for focus** (calm interfaces that leave room for work), **for everyone** (accessibility and inclusion from the start) and **unmistakably Microsoft**.'),
        ], [
            Q('p1', L('Dove si usa Fluent?', 'Where is Fluent used?'), [L('Windows, Microsoft 365, Teams e Azure', 'Windows, Microsoft 365, Teams and Azure'), L('Solo su macOS', 'Only on macOS'), L('Solo nei giochi Xbox', 'Only in Xbox games'), L('Solo su Android', 'Only on Android')], 0, L('L’ecosistema Microsoft.', 'The Microsoft ecosystem.')),
            Q('p2', L('Quale libreria serve per le app Windows native?', 'Which library is for native Windows apps?'), ['WinUI 3', 'SwiftUI', 'Jetpack Compose', 'Vue'], 0, L('Fluent UI React è per il web.', 'Fluent UI React is for the web.')),
            Q('p3', L('Che cosa vuol dire “costruito per la concentrazione”?', 'What does “built for focus” mean?'), [L('Interfacce calme che lasciano spazio al lavoro', 'Calm interfaces that leave room for work'), L('Tante animazioni vistose', 'Lots of flashy animations'), L('Notifiche continue', 'Constant notifications'), L('Colori molto saturi ovunque', 'Very saturated colours everywhere')], 0, L('Il lavoro al centro.', 'Work at the centre.')),
        ], task('text', L('Abbina ogni piattaforma alla libreria Fluent, una riga ciascuna nel formato `piattaforma: libreria`: web, Windows.', 'Match each platform with its Fluent library, one line each in the format `platform: library`: web, Windows.'), "web: \nWindows: ", [re('^web\s*:\s*.*react', L('Web con Fluent UI React', 'Web with Fluent UI React')), re('^windows\s*:\s*.*winui', L('Windows con WinUI', 'Windows with WinUI'))], '', "web: Fluent UI React\nWindows: WinUI 3"), [
            dMatch(pMatch(), [['Fluent UI React', 'Web'], ['WinUI 3', L('App Windows native', 'Native Windows apps')], ['Fluent 2', L('Versione attuale', 'Current version')], ['Teams', L('App che usa Fluent', 'App using Fluent')]], L('L’ecosistema Fluent.', 'The Fluent ecosystem.')),
            dFlash(pFlash(), [[L('Fluent 2 copre anche iOS e Android', 'Fluent 2 also covers iOS and Android'), true], [L('Fluent è il design system di Apple', 'Fluent is Apple’s design system'), false], [L('L’accessibilità è un principio di Fluent', 'Accessibility is a Fluent principle'), true], [L('Fluent si usa solo su Xbox', 'Fluent is used only on Xbox'), false]], L('Conoscere Fluent.', 'Knowing Fluent.')),
        ]),
        lesson('tokens', L('Token, colori e temi', 'Tokens, colours and themes'), [
            P('Fluent 2 si basa sui **design token** in due livelli: **globali** (i valori grezzi, come le rampe di grigio e i colori del brand) e **alias** (il ruolo: `colorNeutralForeground1`, `colorBrandBackground`, `colorNeutralStroke1`). I componenti usano solo gli alias, così i **temi** chiaro, scuro e ad alto contrasto cambiano tutto in un colpo.', 'Fluent 2 is based on **design tokens** in two levels: **global** (raw values, like grey ramps and brand colours) and **alias** (the role: `colorNeutralForeground1`, `colorBrandBackground`, `colorNeutralStroke1`). Components use only aliases, so **light, dark and high-contrast themes** change everything at once.'),
            P('La palette è dominata dai **neutri**, con il colore del **brand** (il blu Microsoft di default, personalizzabile con una rampa di 16 toni) per azioni e selezioni e i colori di **stato** (successo, avviso, errore). Il font è **Segoe UI** su Windows (Segoe UI Variable su Windows 11), e il font di sistema sulle altre piattaforme.', 'The palette is dominated by **neutrals**, with the **brand** colour (Microsoft blue by default, customisable with a 16-tone ramp) for actions and selections and **status** colours (success, warning, error). The font is **Segoe UI** on Windows (Segoe UI Variable on Windows 11), and the system font on other platforms.'),
            C('import { FluentProvider, webLightTheme, Button } from "@fluentui/react-components";

<FluentProvider theme={webLightTheme}>
  <Button appearance="primary">Salva</Button>
</FluentProvider>', 'jsx'),
        ], [
            Q('k1', L('Che cosa indica un token alias come colorBrandBackground?', 'What does an alias token like colorBrandBackground indicate?'), [L('Un ruolo, non un valore fisso', 'A role, not a fixed value'), L('Un colore casuale', 'A random colour'), L('Il nome di un file', 'A file name'), L('Una password', 'A password')], 0, L('I componenti usano gli alias.', 'Components use aliases.')),
            Q('k2', L('Qual è il font di Fluent su Windows 11?', 'What is Fluent’s font on Windows 11?'), ['Segoe UI Variable', 'Roboto', 'SF Pro', 'Comic Sans'], 0, L('Il font di sistema di Windows.', 'The Windows system font.')),
            Q('k3', L('Che cosa fa `FluentProvider` in Fluent UI React?', 'What does `FluentProvider` do in Fluent UI React?'), [L('Applica un tema ai componenti dentro', 'Applies a theme to the components inside'), L('Scarica Windows', 'Downloads Windows'), L('Crea un server', 'Creates a server'), L('Disegna le icone', 'Draws icons')], 0, L('Il tema passa ai figli.', 'The theme flows to children.')),
        ], task('jsx', L('Avvolgi il pulsante in un `FluentProvider` con il tema `webDarkTheme` e rendilo il pulsante principale con `appearance="primary"`.', 'Wrap the button in a `FluentProvider` with the `webDarkTheme` theme and make it the main button with `appearance="primary"`.'), "<Button>Invia</Button>", [re('<FluentProvider\s+theme=\{\s*webDarkTheme\s*\}\s*>', L('Tema scuro', 'Dark theme')), re('<Button[^>]*appearance="primary"', L('Pulsante principale', 'Main button')), re('</FluentProvider>', L('Provider chiuso', 'Provider closed'))], '', "<FluentProvider theme={webDarkTheme}>\n  <Button appearance=\"primary\">Invia</Button>\n</FluentProvider>"), [
            dMatch(pMatch(), [[L('Token globale', 'Global token'), L('Valore grezzo', 'Raw value')], [L('Token alias', 'Alias token'), L('Ruolo del colore', 'Colour role')], ['webLightTheme', L('Tema chiaro', 'Light theme')], ['webDarkTheme', L('Tema scuro', 'Dark theme')], ['Segoe UI', L('Font di Windows', 'Windows font')]], L('Token e temi.', 'Tokens and themes.')),
            dBlanks(pFill(), "<FluentProvider theme={___}>\n  <Button appearance=\"___\">Salva</Button>\n</FluentProvider>", ['webLightTheme', 'primary'], ['lightMode', 'main'], L('Tema e aspetto del pulsante.', 'Theme and button appearance.')),
        ]),
        lesson('materials', L('Materiali: Mica, Acrylic e profondità', 'Materials: Mica, Acrylic and depth'), [
            P('Windows 11 usa **materiali** per dare profondità e contesto. **Mica** è un materiale opaco che prende leggermente la tinta dallo sfondo del desktop: si usa per lo sfondo della finestra dell’app, è leggero per le prestazioni. **Acrylic** è semitrasparente e sfocato come vetro smerigliato: si usa per superfici temporanee come menu a comparsa e pannelli.', 'Windows 11 uses **materials** to add depth and context. **Mica** is an opaque material lightly tinted by the desktop wallpaper: it is used for the app window background and is light on performance. **Acrylic** is semi-transparent and blurred like frosted glass: it is used for transient surfaces such as flyout menus and panels.'),
            P('La **profondità** si costruisce con livelli: sfondo della finestra (Mica), livello del contenuto (carte e superfici in tinta unita), elementi in primo piano con **ombre** morbide in base all’elevazione. Gli **angoli arrotondati** sono regolari: 8 px per finestre e superfici grandi, 4 px per controlli come pulsanti e campi.', '**Depth** is built in layers: the window background (Mica), the content layer (solid cards and surfaces), foreground elements with soft **shadows** by elevation. **Rounded corners** are regular: 8 px for windows and large surfaces, 4 px for controls such as buttons and fields.'),
        ], [
            Q('m1', L('Dove si usa il materiale Mica?', 'Where is the Mica material used?'), [L('Sullo sfondo della finestra dell’app', 'On the app window background'), L('Nei menu a comparsa', 'In flyout menus'), L('Nei pulsanti', 'In buttons'), L('Nelle icone', 'In icons')], 0, L('Leggero e tinto dallo sfondo.', 'Light and tinted by the wallpaper.')),
            Q('m2', L('Che cos’è Acrylic?', 'What is Acrylic?'), [L('Un materiale semitrasparente e sfocato', 'A semi-transparent, blurred material'), L('Un font', 'A font'), L('Un tipo di pulsante', 'A kind of button'), L('Un linguaggio', 'A language')], 0, L('Vetro smerigliato per superfici temporanee.', 'Frosted glass for transient surfaces.')),
            Q('m3', L('Quanto sono arrotondati i controlli in Windows 11?', 'How rounded are controls in Windows 11?'), ['4 px', '0 px', '20 px', '50%'], 0, L('8 px per finestre e superfici grandi.', '8 px for windows and large surfaces.')),
        ], task('css', L('Imita una superficie Acrylic sul `.menu`: sfondo semitrasparente con `rgba(...)`, `backdrop-filter: blur(...)` e `border-radius: 8px`.', 'Imitate an Acrylic surface on `.menu`: a semi-transparent background with `rgba(...)`, `backdrop-filter: blur(...)` and `border-radius: 8px`.'), ".menu {\n  padding: 8px;\n}\n", [re('\.menu\s*\{[^}]*background(-color)?\s*:\s*rgba\(', L('Sfondo semitrasparente', 'Semi-transparent background')), re('\.menu\s*\{[^}]*backdrop-filter\s*:\s*blur\(', L('Sfocatura dello sfondo', 'Background blur')), css('.menu', 'border-top-left-radius', '8px', L('Angoli di 8px', '8px corners'))], '<div class="menu">Copia · Incolla · Elimina</div>', ".menu {\n  background: rgba(255, 255, 255, .7);\n  backdrop-filter: blur(30px);\n  border-radius: 8px;\n}"), [
            dMatch(pMatch(), [['Mica', L('Sfondo della finestra', 'Window background')], ['Acrylic', L('Menu e pannelli temporanei', 'Transient menus and panels')], ['8 px', L('Angoli di finestre e superfici', 'Window and surface corners')], ['4 px', L('Angoli dei controlli', 'Control corners')], [L('Ombre', 'Shadows'), L('Elevazione', 'Elevation')]], L('I materiali di Windows.', 'Windows materials.')),
            dFlash(pFlash(), [[L('Mica è pensato per essere leggero sulle prestazioni', 'Mica is designed to be light on performance'), true], [L('Acrylic si usa per lo sfondo di ogni finestra', 'Acrylic is used for every window background'), false], [L('In Windows 11 gli angoli sono arrotondati', 'In Windows 11 corners are rounded'), true], [L('Fluent non usa ombre', 'Fluent uses no shadows'), false]], L('Profondità e materiali.', 'Depth and materials.')),
        ]),
        lesson('windows', L('Layout e componenti delle app Windows', 'Windows app layouts and components'), [
            P('Le app Windows usano una **NavigationView**: barra laterale a sinistra con le sezioni (che si compatta in sole icone o diventa un menu quando la finestra si stringe) oppure in alto per poche sezioni. La **barra del titolo** può ospitare ricerca e azioni; la **CommandBar** raccoglie i comandi principali con le loro icone e un menu “altro”.', 'Windows apps use a **NavigationView**: a left sidebar with the sections (compacting to icons only or becoming a menu when the window narrows) or at the top for few sections. The **title bar** can host search and actions; the **CommandBar** gathers the main commands with their icons and a “more” menu.'),
            P('Componenti tipici: **ContentDialog** per conferme, **InfoBar** per messaggi persistenti in pagina, **TeachingTip** per spiegare una novità, **TreeView** e **ListView**, **Flyout** e menu contestuali. Le app devono funzionare bene con **mouse, tastiera, penna e touch** e supportare lo **Snap Layout** di Windows 11, adattando il layout a ogni dimensione di finestra.', 'Typical components: **ContentDialog** for confirmations, **InfoBar** for persistent in-page messages, **TeachingTip** to explain something new, **TreeView** and **ListView**, **Flyouts** and context menus. Apps must work well with **mouse, keyboard, pen and touch** and support Windows 11 **Snap Layouts**, adapting the layout to every window size.'),
            C('<NavigationView PaneDisplayMode="Auto">
  <NavigationView.MenuItems>
    <NavigationViewItem Content="Home" Icon="Home"/>
    <NavigationViewItem Content="Documenti" Icon="Document"/>
  </NavigationView.MenuItems>
  <Frame x:Name="Contenuto"/>
</NavigationView>', 'text'),
        ], [
            Q('w1', L('Che cosa fa la NavigationView quando la finestra si stringe?', 'What does NavigationView do when the window narrows?'), [L('Si compatta in icone o diventa un menu', 'Compacts to icons or becomes a menu'), L('Sparisce per sempre', 'Disappears forever'), L('Si ingrandisce', 'Grows larger'), L('Chiude l’app', 'Closes the app')], 0, L('Layout adattivo.', 'Adaptive layout.')),
            Q('w2', L('Quale componente spiega una novità vicino a un controllo?', 'Which component explains something new near a control?'), ['TeachingTip', 'TreeView', 'CommandBar', 'Frame'], 0, L('Un suggerimento contestuale.', 'A contextual tip.')),
            Q('w3', L('Quali input deve supportare un’app Windows?', 'Which inputs should a Windows app support?'), [L('Mouse, tastiera, penna e touch', 'Mouse, keyboard, pen and touch'), L('Solo il mouse', 'Only the mouse'), L('Solo il touch', 'Only touch'), L('Solo la voce', 'Only voice')], 0, L('Naturale su ogni dispositivo.', 'Natural on every device.')),
        ], task('text', L('Abbina ogni esigenza al componente Windows, una riga ciascuna nel formato `esigenza: componente`: conferma prima di eliminare, avviso “sei offline” in cima alla pagina, comandi principali di un editor.', 'Match each need with a Windows component, one line each in the format `need: component`: confirm before deleting, “you are offline” notice at the top of the page, an editor’s main commands.'), '', [re('(elimin|delet)[^\n]*:\s*contentdialog', L('ContentDialog per confermare', 'ContentDialog to confirm')), re('(offline)[^\n]*:\s*infobar', L('InfoBar per l’avviso', 'InfoBar for the notice')), re('(comand|command)[^\n]*:\s*commandbar', L('CommandBar per i comandi', 'CommandBar for commands'))], '', "conferma prima di eliminare: ContentDialog\navviso sei offline: InfoBar\ncomandi principali: CommandBar"), [
            dMatch(pMatch(), [['NavigationView', L('Sezioni dell’app', 'App sections')], ['CommandBar', L('Comandi principali', 'Main commands')], ['ContentDialog', L('Conferme', 'Confirmations')], ['InfoBar', L('Messaggi persistenti', 'Persistent messages')], ['Snap Layout', L('Finestre affiancate', 'Side-by-side windows')]], L('Componenti Windows.', 'Windows components.')),
            dFlash(pFlash(), [[L('Le app Windows dovrebbero supportare Snap Layout', 'Windows apps should support Snap Layouts'), true], [L('La NavigationView sta sempre e solo in basso', 'NavigationView is always and only at the bottom'), false], [L('Una InfoBar mostra messaggi nella pagina', 'An InfoBar shows messages in the page'), true], [L('La penna non va considerata', 'The pen should not be considered'), false]], L('App Windows ben fatte.', 'Well-made Windows apps.')),
        ]),
        lesson('code', L('Fluent nel codice', 'Fluent in code'), [
            P('Per il web Microsoft offre **Fluent UI React** (v9): componenti come `Button`, `Input`, `Dialog` già accessibili, con i token di Fluent 2. L’app si avvolge in un `FluentProvider` che sceglie il tema, chiaro, scuro o ad alto contrasto.', 'For the web Microsoft offers **Fluent UI React** (v9): components such as `Button`, `Input`, `Dialog`, already accessible, with Fluent 2 tokens. The app is wrapped in a `FluentProvider` that picks the theme, light, dark or high contrast.'),
            C('import { FluentProvider, webLightTheme, Button } from "@fluentui/react-components";

export function App() {
  return (
    <FluentProvider theme={webLightTheme}>
      <Button appearance="primary">Salva</Button>
    </FluentProvider>
  );
}', 'jsx'),
            P('Per le app Windows native c’è **WinUI 3**, con controlli in XAML che usano già Mica, i colori d’accento dell’utente e i temi di sistema. Su entrambi, usa i **token** invece di valori fissi: così il tema scuro e l’alto contrasto funzionano da soli.', 'For native Windows apps there is **WinUI 3**, with XAML controls already using Mica, the user’s accent colours and system themes. On both, use **tokens** instead of fixed values: that way dark theme and high contrast just work.'),
        ], [
            Q('fc1', L('Che cosa fa `FluentProvider`?', 'What does `FluentProvider` do?'), [L('Applica il tema ai componenti', 'Applies the theme to components'), L('Carica i font da Google', 'Loads fonts from Google'), L('Crea le rotte', 'Creates routes'), L('Gestisce il login', 'Handles login')], 0, L('Chiaro, scuro, alto contrasto.', 'Light, dark, high contrast.')),
            Q('fc2', L('Con che cosa si fanno le app Windows native Fluent?', 'What are native Fluent Windows apps built with?'), ['WinUI 3', 'jQuery', 'Bootstrap', 'SwiftUI'], 0, L('Controlli XAML.', 'XAML controls.')),
            Q('fc3', L('Perché usare i token invece di colori fissi?', 'Why use tokens instead of fixed colours?'), [L('Temi scuro e alto contrasto funzionano da soli', 'Dark and high-contrast themes just work'), L('Sono più corti da scrivere', 'They are shorter to write'), L('Lo chiede la legge', 'The law requires it'), L('Non c’è differenza', 'There is no difference')], 0, L('Il valore cambia con il tema.', 'The value changes with the theme.')),
        ], task('jsx', L('Avvolgi un `<Button appearance="primary">` in `<FluentProvider theme={webLightTheme}>`.', 'Wrap a `<Button appearance="primary">` in `<FluentProvider theme={webLightTheme}>`.'), '', [re('<FluentProvider\s+theme\s*=\s*\{\s*webLightTheme\s*\}\s*>', L('Il tema è applicato', 'The theme is applied')), re('<Button\s+appearance\s*=\s*["\']primary["\']\s*>', L('C’è il pulsante primario', 'The primary button is there')), re('</FluentProvider>', L('Il provider è chiuso', 'The provider is closed'))], '', "<FluentProvider theme={webLightTheme}>\n  <Button appearance=\"primary\">Salva</Button>\n</FluentProvider>"), [
            dOrder(pSort(), ['import { FluentProvider, webLightTheme, Button } from "@fluentui/react-components";', 'export function App() {', '  return (', '    <FluentProvider theme={webLightTheme}>', '      <Button appearance="primary">Salva</Button>', '    </FluentProvider>', '  );', '}'], L('Import, provider, componente.', 'Import, provider, component.')),
            dFlash(pFlash(), [[L('I componenti Fluent UI React sono già accessibili', 'Fluent UI React components are already accessible'), true], [L('WinUI 3 serve per i siti web', 'WinUI 3 is for websites'), false], [L('I token rendono facile il tema scuro', 'Tokens make dark theme easy'), true], [L('FluentProvider va messo dentro ogni pulsante', 'FluentProvider goes inside every button'), false]], L('Fluent per sviluppatori.', 'Fluent for developers.')),
        ]),
    ],
